const fs = require("node:fs");
const path = require("node:path");
const { withDangerousMod, withMainApplication } = require("expo/config-plugins");

// Daseo delta 63: a native-heap watchdog that asks the JS VM to collect before Fabric's stale
// shadow nodes exhaust native memory (getpaseo/paseo#4408), and previous-exit reporting so a
// native crash still reaches daemon.log. `android/` is generated by prebuild, so the Kotlin
// source lives here as a template and MainApplication is patched on every prebuild.
const TEMPLATE = path.join(__dirname, "android-memory-guard", "DaseoMemoryGuard.kt.template");
const LIFECYCLE_LINE = "ApplicationLifecycleDispatcher.onApplicationCreate(this)";
const START_LINE = "DaseoMemoryGuard.start(this) { reactHost }";

function writeMemoryGuardSource(config) {
  return withDangerousMod(config, [
    "android",
    async (modConfig) => {
      const packageName = modConfig.android?.package;
      if (!packageName) throw new Error("Daseo memory guard needs android.package");
      const directory = path.join(
        modConfig.modRequest.platformProjectRoot,
        "app",
        "src",
        "main",
        "java",
        ...packageName.split("."),
      );
      fs.mkdirSync(directory, { recursive: true });
      const source = fs.readFileSync(TEMPLATE, "utf8").replace("__PACKAGE__", packageName);
      fs.writeFileSync(path.join(directory, "DaseoMemoryGuard.kt"), source);
      return modConfig;
    },
  ]);
}

function startMemoryGuard(contents) {
  if (contents.includes(START_LINE)) return contents;
  if (!contents.includes(LIFECYCLE_LINE)) {
    throw new Error(
      `Could not find "${LIFECYCLE_LINE}" in MainApplication to start the memory guard`,
    );
  }
  return contents.replace(
    LIFECYCLE_LINE,
    `${LIFECYCLE_LINE}\n    // Daseo delta 63: native-heap watchdog and previous-exit reporting.\n    ${START_LINE}`,
  );
}

function withAndroidMemoryGuard(config) {
  const withSource = writeMemoryGuardSource(config);
  return withMainApplication(withSource, (modConfig) => {
    if (modConfig.modResults.language !== "kt") {
      throw new Error("Daseo memory guard expects a Kotlin MainApplication");
    }
    modConfig.modResults.contents = startMemoryGuard(modConfig.modResults.contents);
    return modConfig;
  });
}

module.exports = withAndroidMemoryGuard;
module.exports.startMemoryGuard = startMemoryGuard;
